L1: import { execFile } from "node:child_process";
L2: import { randomBytes } from "node:crypto";
L3: // Where the message server listens. Only Tailscale listens on a non-loopback address, and only on the
L4: // device's Tailscale address, so the server is never reachable from other networks.
L5: export async function listenAddress(mode) {
L6:     if (mode !== "tailscale")
L7:         return "127.0.0.1";
L8:     return tailscaleAddress();
L9: }
L10: export async function expose(mode, hostname, port) {
L11:     if (mode === "opentunnel")
L12:         return openTunnel(port);
L13:     return { url: `http://${hostname}:${port}`, close: async () => { } };
L14: }
L15: // Shares the device's OpenTunnel tunnel (the same one `opencode pair --remote` uses) and claims a
L16: // random route on it. The route keeps the URL unguessable; the invite token is the actual auth.
L17: async function openTunnel(port) {
L18:     const { create } = await import("@opentunnel/client");
L19:     const client = create();
L20:     const route = randomBytes(8).toString("hex");
L21:     try {
L22:         const connection = await client.tunnel.connect({ routes: { [route]: `127.0.0.1:${port}` } });
L23:         return {
L24:             url: `https://${route}.${connection.tunnel.hostname}`,
L25:             async close() {
L26:                 await connection.close().catch(() => undefined);
L27:                 await client.dispose().catch(() => undefined);
L28:             },
L29:         };
L30:     }
L31:     catch (error) {
L32:         await client.dispose().catch(() => undefined);
L33:         throw error;
L34:     }
L35: }
L36: // The macOS app ships its CLI inside the bundle and doesn't always put `tailscale` on PATH.
L37: const TAILSCALE = ["tailscale", "/Applications/Tailscale.app/Contents/MacOS/Tailscale"];
L38: async function tailscaleAddress() {
L39:     for (const command of TAILSCALE) {
L40:         const output = await new Promise((resolve) => {
L41:             execFile(command, ["ip", "-4"], { timeout: 5_000 }, (error, stdout) => resolve(error ? undefined : stdout));
L42:         });
L43:         const address = output?.split("\n").map((line) => line.trim()).find(Boolean);
L44:         if (address)
L45:             return address;
L46:     }
L47:     throw new Error("Couldn't get this device's Tailscale address. Is Tailscale installed and connected?");
